def load_events(events_path: Path, strict: bool = False) -> List[Dict[str, Any]]:
    """Parse and chronologically order `events.jsonl` per `swarm/CONTRACT.md`."""
    indexed: List[Tuple[int, int, Dict[str, Any]]] = []
    raw_text = events_path.read_text(encoding="utf-8")
    for line_no, raw_line in enumerate(raw_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            if strict:
                raise
            continue
        if not isinstance(rec, dict):
            if strict:
                raise ValueError(f"{events_path}:{line_no}: expected JSON object")
            continue
        if strict and rec.get("v") != 1:
            raise ValueError(f"{events_path}:{line_no}: expected v == 1, got {rec.get('v')!r}")
        rec_type = rec.get("rec")
        if rec_type not in VALID_REC_TYPES:
            if strict:
                raise ValueError(f"{events_path}:{line_no}: unknown rec {rec_type!r}")
            continue
        ts_val = rec.get("ts_ms")
        if ts_val is None and rec_type == "claim":
            ts_val = rec.get("issued_ts_ms")
        if ts_val is None:
            if strict:
                raise ValueError(f"{events_path}:{line_no}: missing ts_ms on {rec_type!r}")
            ts_int = 0
        else:
            if isinstance(ts_val, bool):
                if strict:
                    raise ValueError(f"{events_path}:{line_no}: invalid boolean ts_ms {ts_val!r}")
                continue
            try:
                ts_int = int(ts_val)
            except (TypeError, ValueError):
                if strict:
                    raise ValueError(f"{events_path}:{line_no}: invalid ts_ms {ts_val!r}")
                continue
        normalized = dict(rec)
        normalized["_ts_ms"] = ts_int
        normalized["_line_no"] = line_no
        indexed.append((ts_int, line_no, normalized))

    # Preserve file line order (_line_no) on equal timestamps
    indexed.sort(key=lambda item: (item[0], item[1]))
    return [item[2] for item in indexed]


def _discover_sidecar(input_path: Path, explicit_sidecar: Optional[Path]) -> Optional[Dict[str, Any]]:
    candidates: List[Path] = []
    if explicit_sidecar is not None:
        candidates.append(explicit_sidecar)
    else:
        candidates.extend(
            [
                Path(f"{input_path}.meta.json"),
                Path(f"{input_path}.json"),
                input_path.with_suffix(".meta.json"),
                input_path.with_suffix(".json"),
            ]
        )
    for cand in candidates:
        if cand.is_file():
            try:
                data = json.loads(cand.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    return data
            except (OSError, json.JSONDecodeError):
                continue
    return None


def evaluate_agent_cursor(
    agent_id: str,
    cursor_events: Sequence[Dict[str, Any]],
    cursor_ts_list: Sequence[int],
    cur_ts_ms: float,
    lerp_ts_ms: float,
    close_by_event: Dict[Tuple[str, str], Dict[str, Any]],
) -> CursorVisualState:
    """Evaluate smoothstep-interpolated cursor `(x, y)` and visual phase at `cur_ts_ms`."""
    spec = AGENT_SPECS.get(
        agent_id,
        {"color": "#e2e8f0", "rgb": (226, 232, 240), "slot": (960.0, 540.0), "default_lane": "SCRIPT"},
    )
    default_x, default_y = spec["slot"]
    default_rgb: Tuple[int, int, int] = spec["rgb"]

    # Binary search for latest cursor record with _ts_ms <= cur_ts_ms
    upto = bisect.bisect_right(cursor_ts_list, cur_ts_ms)
    def advance_to(self, cur_ts_ms: float) -> None:
        n = len(self.events)
        while self.idx < n and float(self.events[self.idx]["_ts_ms"]) <= cur_ts_ms:
            self._apply(self.events[self.idx])
            self.idx += 1

    def _apply(self, rec: Dict[str, Any]) -> None:
        rtype = rec.get("rec")
        if rtype == "enqueue":
            aid = str(rec.get("agent_id") or "")
            eid = rec.get("event_id")
            if aid and eid:
                fifo = self.pending_fifo.setdefault(aid, [])
                if not any(item.get("event_id") == eid for item in fifo):
                    fifo.append(rec)
                if aid == self.active_head and self.active_lane in {"READY", "IDLE", "PASS"}:
                    self.active_lane = str(rec.get("lane") or "script").upper()

        elif rtype == "turn":
            if rec.get("turn") is not None:
                self.turn_num = int(rec["turn"])
            aid = str(rec.get("agent_id") or "")
            if aid:
                self.active_head = aid
                fifo = self.pending_fifo.get(aid) or []
                if fifo:
                    self.active_lane = str(fifo[0].get("lane") or "script").upper()
                else:
                    spec = AGENT_SPECS.get(aid)
                    self.active_lane = spec["default_lane"] if spec else "SCRIPT"

        elif rtype == "close":
            if rec.get("turn") is not None:
                self.turn_num = int(rec["turn"])
            if rec.get("tick") is not None:
                self.tick_num = int(rec["tick"])
            aid = str(rec.get("agent_id") or "")
            eid = rec.get("event_id")
            verdict = str(rec.get("verdict") or "")
            is_enqueue_refusal = verdict in ENQUEUE_REFUSAL_VERDICTS
            if rec.get("lane") and not is_enqueue_refusal:
                self.active_lane = str(rec["lane"]).upper()
            if aid and eid is not None and not is_enqueue_refusal:
                self.close_by_event[(aid, str(eid))] = rec
                fifo = self.pending_fifo.setdefault(aid, [])
                matched = [item for item in fifo if item.get("event_id") == eid]
                remaining = [item for item in fifo if item.get("event_id") != eid]
                if verdict == "STALE_FRAME":
                    drops = int(rec.get("drops") or 1)
                    if drops >= 3:
                        # Parks only this stale event; agent stays active for future turns
                        self.pending_fifo[aid] = remaining
                    else:
                        # Requeue at agent FIFO tail per CONTRACT.md Section 3.1.4
                        self.pending_fifo[aid] = remaining + matched
                elif verdict != "PASS":
                    self.pending_fifo[aid] = remaining

            if verdict == "PASS":
                self.last_pass_rec = rec
            elif verdict:
                self.last_verdict_rec = rec

        elif rtype == "control":
            op = str(rec.get("op") or "").lower()
            if op == "park":
                target = str(rec.get("agent_id") or "")
                reason = str(rec.get("reason") or "")
                event_id = rec.get("event_id")
                is_stale_drop_event_park = reason.startswith("parked_after_3_stale_drops")
                is_timeout_agent_park = "turn_timeout" in reason.lower()
                if not is_stale_drop_event_park:
                    if is_timeout_agent_park:
                        if target:
                            self.parked_agents.add(target)
                        else:
                            for candidate in RING_ORDER:
                                if candidate in reason:
                                    self.parked_agents.add(candidate)
                    elif target and not event_id:
                        self.parked_agents.add(target)
                    elif not target and not event_id:
                        for candidate in RING_ORDER:
                            if candidate in reason:
                                self.parked_agents.add(candidate)
            elif op == "resume":
                self.control_state = None
                target = str(rec.get("agent_id") or "")
                if target:
                    self.parked_agents.discard(target)
                else:
                    self.parked_agents.clear()
            elif op in {"stop", "reconcile", "checkpoint"}:
                self.control_state = rec

    def waiting_ring(self) -> List[str]:
        if self.active_head in RING_ORDER:
            head_idx = RING_ORDER.index(self.active_head)
            return [RING_ORDER[(head_idx + offset) % len(RING_ORDER)] for offset in range(1, len(RING_ORDER))]
        return list(RING_ORDER)

    def strip_cache_key(self) -> Tuple[Any, ...]:
        vrec = self.last_verdict_rec or self.last_pass_rec
        v_tuple = (
            vrec.get("verdict") if vrec else None,
            bool(vrec.get("rebased")) if vrec else False,
            int(vrec.get("drops") or 0) if vrec else 0,
            vrec.get("agent_id") if vrec else None,
        )
        fifo_counts = tuple((a, len(self.pending_fifo.get(a) or ()), a in self.parked_agents) for a in RING_ORDER)
        ctrl = (self.control_state.get("op"), self.control_state.get("by")) if self.control_state else None
        return (self.turn_num, self.tick_num, self.active_head, self.active_lane, fifo_counts, v_tuple, ctrl)


